<template><div class="app-page"><div class="app-page-inner-wide">
  <section class="app-hero-panel flex flex-col gap-5 lg:flex-row lg:items-end lg:justify-between"><div><p class="app-eyebrow">Data Operations</p><h1 class="app-title mt-2">{{ t('dataHealth.title') }}</h1><p class="app-subtitle mt-3">{{ t('dataHealth.subtitle') }}</p></div><div class="flex gap-2"><button type="button" class="app-button-secondary" :disabled="loading" @click="load">{{ t('dataHealth.refresh') }}</button><button type="button" class="app-button-primary" :disabled="repairing" @click="repair('verify_database')">{{ t('dataHealth.verifyDb') }}</button></div></section>
  <div v-if="error" class="border border-rose-200 bg-rose-50 px-4 py-3 text-sm text-rose-700 dark:border-rose-900 dark:bg-rose-950/30 dark:text-rose-200" role="alert">{{ error }}</div><div v-if="feedback" class="border border-emerald-200 bg-emerald-50 px-4 py-3 text-sm text-emerald-800 dark:border-emerald-900 dark:bg-emerald-950/30 dark:text-emerald-200" role="status">{{ feedback }}</div>
  <section v-if="health" class="grid gap-3 sm:grid-cols-2 xl:grid-cols-4"><article class="app-panel p-5"><p class="text-xs app-muted">{{ t('dataHealth.overall') }}</p><p class="mt-2 text-xl font-semibold" :class="statusTone(health.status)">{{ statusLabel(health.status) }}</p></article><article class="app-panel p-5"><p class="text-xs app-muted">{{ t('dataHealth.revision') }}</p><p class="mt-2 text-xl font-semibold">{{ health.databaseRevision || '--' }}</p></article><article class="app-panel p-5"><p class="text-xs app-muted">{{ t('dataHealth.sources') }}</p><p class="mt-2 text-xl font-semibold">{{ health.sources?.length || 0 }}</p></article><article class="app-panel p-5"><p class="text-xs app-muted">{{ t('dataHealth.problems') }}</p><p class="mt-2 text-xl font-semibold text-amber-600">{{ health.summary?.problemSourceCount || 0 }}</p></article></section>
  <section class="app-panel p-5"><div class="flex flex-col gap-4 lg:flex-row lg:items-end lg:justify-between"><div><h2 class="app-section-title">{{ t('dataHealth.repairHistory') }}</h2><p class="mt-1 text-sm app-muted">{{ t('dataHealth.repairHint') }}</p></div><div class="grid gap-2 sm:grid-cols-[12rem_7rem_7rem_auto]"><input v-model.trim="symbol" class="app-control" placeholder="BTC/USDT" /><select v-model="timeframe" class="app-control"><option value="1h">1h</option><option value="4h">4h</option><option value="1d">1d</option></select><input v-model.number="days" type="number" min="1" max="3650" class="app-control" /><button type="button" class="app-button-secondary" :disabled="repairing || !symbol" @click="repair('hydrate_symbol_history')">{{ t('dataHealth.hydrate') }}</button></div></div></section>
  <section class="grid gap-4 lg:grid-cols-2"><article v-for="source in health?.sources || []" :key="source.id" class="app-panel p-5"><div class="flex items-start justify-between gap-4"><div><h2 class="font-semibold text-stone-950 dark:text-white">{{ source.name }}</h2><p class="mt-1 text-sm app-muted">{{ source.detail }}</p></div><span class="app-chip" :class="statusTone(source.status)">{{ statusLabel(source.status) }}</span></div><dl class="mt-4 grid grid-cols-2 gap-3 text-sm xl:grid-cols-4"><div><dt class="app-muted">{{ t('dataHealth.records') }}</dt><dd class="mt-1 font-semibold">{{ source.recordCount }}</dd></div><div><dt class="app-muted">{{ t('dataHealth.gaps') }}</dt><dd class="mt-1 font-semibold">{{ source.gapCount ?? '--' }}</dd></div><div><dt class="app-muted">{{ t('dataHealth.coverageStart') }}</dt><dd class="mt-1 font-semibold">{{ dateTime(source.coverageStart) }}</dd></div><div><dt class="app-muted">{{ t('dataHealth.coverageEnd') }}</dt><dd class="mt-1 font-semibold">{{ dateTime(source.coverageEnd) }}</dd></div><div><dt class="app-muted">{{ t('dataHealth.age') }}</dt><dd class="mt-1 font-semibold">{{ age(source.ageSeconds) }}</dd></div><div v-if="source.lastSuccessAt"><dt class="app-muted">{{ t('dataHealth.lastSuccess') }}</dt><dd class="mt-1 font-semibold">{{ dateTime(source.lastSuccessAt) }}</dd></div><div v-if="source.lastFailureAt"><dt class="app-muted">{{ t('dataHealth.lastFailure') }}</dt><dd class="mt-1 font-semibold">{{ dateTime(source.lastFailureAt) }}</dd></div><div v-if="source.nextRunAt"><dt class="app-muted">{{ t('dataHealth.nextRun') }}</dt><dd class="mt-1 font-semibold">{{ dateTime(source.nextRunAt) }}</dd></div></dl><div v-if="source.repairActions?.length" class="mt-4 flex flex-wrap gap-2"><button v-for="action in source.repairActions" :key="action" type="button" class="app-button-secondary text-xs" :disabled="repairing || action==='hydrate_symbol_history'" @click="repair(action)">{{ actionLabel(action) }}</button></div></article></section>
  <section class="app-panel p-5"><h2 class="app-section-title">{{ t('dataHealth.jobs') }}</h2><div class="mt-4 flex flex-wrap gap-2"><button type="button" class="app-button-secondary" :disabled="repairing" @click="repair('refresh_binance_snapshot')">{{ t('dataHealth.refreshBinance') }}</button><button type="button" class="app-button-secondary" :disabled="repairing" @click="repair('evaluate_research_alerts')">{{ t('dataHealth.checkAlerts') }}</button><button type="button" class="app-button-secondary" :disabled="repairing" @click="repair('evaluate_trade_signals')">{{ t('dataHealth.checkSignals') }}</button></div></section>
</div></div></template>
<script setup lang="ts">import { onMounted,ref } from 'vue';import { useI18n } from 'vue-i18n';import { systemApi } from '@/modules/system/api';import type { DataHealthResponse,DataRepairCommand } from '@/modules/system/contracts';const {t}=useI18n();const health=ref<DataHealthResponse|null>(null);const loading=ref(false),repairing=ref(false),error=ref(''),feedback=ref(''),symbol=ref('BTC/USDT'),timeframe=ref('1h'),days=ref(365);const load=async()=>{loading.value=true;error.value='';try{health.value=await systemApi.getDataHealth()}catch(e){error.value=e instanceof Error?e.message:String(e)}finally{loading.value=false}};const repair=async(action:string)=>{repairing.value=true;error.value='';feedback.value='';try{const result=await systemApi.repairData({action:action as DataRepairCommand['action'],symbol:symbol.value||null,timeframe:timeframe.value,days:days.value});feedback.value=result.detail;await load()}catch(e){error.value=e instanceof Error?e.message:String(e)}finally{repairing.value=false}};const statusLabel=(v:string)=>t(`dataHealth.status.${v}`);const statusTone=(v:string)=>v==='ready'||v==='healthy'?'text-emerald-700 dark:text-emerald-300':v==='empty'||v==='starting'?'text-stone-600 dark:text-slate-300':'text-amber-700 dark:text-amber-300';const dateTime=(v?:string|null)=>v?new Date(v).toLocaleString():'--';const age=(v?:number|null)=>v==null?'--':v<3600?`${Math.round(v/60)}m`:v<86400?`${(v/3600).toFixed(1)}h`:`${(v/86400).toFixed(1)}d`;const actionLabel=(v:string)=>t(`dataHealth.actions.${v}`);onMounted(load)</script>
